			if kst := time.Now().In(market.KST); kst.Hour() < 16 || (kst.Hour() == 16 && kst.Minute() < 5) {
				target := time.Date(kst.Year(), kst.Month(), kst.Day(), 16, 5, 0, 0, market.KST)
				if d := time.Until(target); d > 0 && d < wait {
					slog.Info("일봉 확정 대기 후 축적", "until", target.Format("15:04"))
					time.Sleep(d)
					wait -= d
				}
			}
			accumulateCandles(c, cfg, false)
			if time.Now().In(market.KST).Weekday() == time.Saturday {
				researchWeekly(c, cfg, false)
			}
			opsDigest(cfg, cycle+1, wait)
		}
		slog.Info("데몬 대기", "cycle", cycle+1, "next_session_in", wait.Truncate(time.Minute))
		{
			mc := cfg.ForMarket(markets[0])
			sleepWithHeartbeat(wait, cfg.DataDir, agent.Heartbeat{Key: journal.KeyTag(cfg.Mode, markets[0], cfg.Tag), Kind: "intraday", Mode: cfg.Mode, Market: markets[0], Tag: cfg.Tag,
				Strategy: mc.Strategy, Currency: mc.Currency, Detail: fmt.Sprintf("다음 세션까지 대기 (%s)", wait.Truncate(time.Minute))})
		}
		sort.SliceStable(markets, func(i, j int) bool {
			return nextSessionDelay(cfg.ForMarket(markets[i]), time.Now()) < nextSessionDelay(cfg.ForMarket(markets[j]), time.Now())
		})
	}
}

