func TestEnabled(t *testing.T) {
	var nilN *Notifier
	if nilN.Enabled() {
		t.Fatal("nil notifier must be disabled")
	}
	cases := []struct {
		tok, chat, slack string
		want             bool
	}{
		{"", "", "", false},
		{"tok", "", "", false}, // 토큰만 있고 채팅 ID 가 없으면 무효
		{"", "chat", "", false},
		{"tok", "chat", "", true},
		{"", "", "https://hooks.slack/x", true},
	}
	for _, c := range cases {
		if got := New(c.tok, c.chat, c.slack).Enabled(); got != c.want {
			t.Errorf("Enabled(%q,%q,%q)=%v want %v", c.tok, c.chat, c.slack, got, c.want)
		}
	}
}

// 텔레그램: bot<token>/sendMessage 에 chat_id·text 폼으로 보낸다.
func TestSendTelegram(t *testing.T) {
	var gotPath, gotChat, gotText string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		gotPath = r.URL.Path
		if err := r.ParseForm(); err != nil {
			t.Errorf("parse form: %v", err)
		}
		gotChat, gotText = r.FormValue("chat_id"), r.FormValue("text")
		w.WriteHeader(200)
	}))
	defer srv.Close()
	n := New("TOKEN", "123", "")
	n.telegramBase = srv.URL
	n.send("hello **bold**")
	if gotPath != "/botTOKEN/sendMessage" || gotChat != "123" || gotText != "hello **bold**" {
		t.Fatalf("path=%q chat=%q text=%q", gotPath, gotChat, gotText)
	}
}

// 슬랙: JSON {"text": ...} 로 보내며 마크다운 굵게(**) 는 슬랙 문법(*) 으로 바꾼다.
func TestSendSlack(t *testing.T) {
	var got map[string]string
	var gotCT string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		gotCT = r.Header.Get("Content-Type")
		b, _ := io.ReadAll(r.Body)
		if err := json.Unmarshal(b, &got); err != nil {
			t.Errorf("body %q: %v", b, err)
		}
	}))
	defer srv.Close()
	n := New("", "", srv.URL)
	n.send("손익 **+1,000원**")
	if gotCT != "application/json" || got["text"] != "손익 *+1,000원*" {
		t.Fatalf("ct=%q body=%v", gotCT, got)
	}
}

// 구조체 리터럴로 만든 Notifier (http 필드 nil) 도 패닉 없이 전송한다.
func TestStructLiteralDoesNotPanic(t *testing.T) {
	hits := 0
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { hits++ }))
	defer srv.Close()
	n := &Notifier{SlackWebhook: srv.URL}
	n.send("x")
	n.send("y")
	if hits != 2 {
		t.Fatalf("hits=%d", hits)
	}
	if n.http == nil || n.http.Timeout == 0 {
		t.Fatal("http client must be lazily initialised with a timeout")
	}
}

// 서버 오류(4xx/5xx) 나 연결 실패는 로그만 남기고 돌아온다 (best-effort).
func TestSendFailuresAreSwallowed(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { w.WriteHeader(500) }))
	n := New("T", "C", srv.URL)
	n.telegramBase = srv.URL
	n.send("a")
	srv.Close()
	n.send("b") // 닫힌 서버 → 연결 실패
}
