package copilot

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/url"
	"strconv"
	"strings"
	"time"
)

// Bot: 텔레그램 Bot API 최소 클라이언트 (긴 폴링 + 인라인 버튼).
type Bot struct {
	Token string
	Chat  string // 허용된 채팅 ID — 이 채팅의 메시지만 처리한다
	Base  string // 테스트용 (비어 있으면 api.telegram.org)
	http  *http.Client
}

func NewBot(token, chat string) *Bot {
	return &Bot{Token: token, Chat: chat, http: &http.Client{Timeout: 40 * time.Second}}
}

func (b *Bot) base() string {
	if b.Base != "" {
		return b.Base
	}
	return "https://api.telegram.org"
}

// Update: 필요한 필드만.
type Update struct {
	ID      int64 `json:"update_id"`
	Message *struct {
		ID   int64  `json:"message_id"`
		Text string `json:"text"`
		Chat struct {
			ID int64 `json:"id"`
		} `json:"chat"`
		From struct {
			ID       int64  `json:"id"`
			Username string `json:"username"`
		} `json:"from"`
	} `json:"message"`
	Callback *struct {
		ID   string `json:"id"`
		Data string `json:"data"`
		Msg  *struct {
			ID   int64 `json:"message_id"`
			Chat struct {
				ID int64 `json:"id"`
			} `json:"chat"`
		} `json:"message"`
		From struct {
			ID int64 `json:"id"`
		} `json:"from"`
	} `json:"callback_query"`
}

func (b *Bot) call(method string, form url.Values, out any) error {
	resp, err := b.http.PostForm(b.base()+"/bot"+b.Token+"/"+method, form)
	if err != nil {
		// 오류 문자열에 URL(토큰 포함)이 들어간다 — 로그에 남지 않게 지운다
		return fmt.Errorf("telegram %s: %s", method, strings.ReplaceAll(err.Error(), b.Token, "***"))
	}
	defer resp.Body.Close()
	var env struct {
		OK          bool            `json:"ok"`
		Description string          `json:"description"`
		Result      json.RawMessage `json:"result"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&env); err != nil {
		return err
	}
	if !env.OK {
		return fmt.Errorf("telegram %s: %s", method, env.Description)
	}
	if out != nil {
		return json.Unmarshal(env.Result, out)
	}
	return nil
}

// Updates: offset 이후 업데이트를 최대 timeout 초 기다려 받는다.
func (b *Bot) Updates(offset int64, timeout int) ([]Update, error) {
	var out []Update
	err := b.call("getUpdates", url.Values{"offset": {strconv.FormatInt(offset, 10)}, "timeout": {strconv.Itoa(timeout)}, "allowed_updates": {`["message","callback_query"]`}}, &out)
	return out, err
}

// Button: 인라인 버튼 (callback_data ≤ 64 bytes).
type Button struct{ Text, Data string }

// Send: 텍스트(+버튼) 전송. 반환: message_id.
func (b *Bot) Send(text string, rows ...[]Button) (int64, error) {
	form := url.Values{"chat_id": {b.Chat}, "text": {text}, "disable_web_page_preview": {"true"}}
	if len(rows) > 0 {
		var kb [][]map[string]string
		for _, r := range rows {
			var row []map[string]string
			for _, x := range r {
				row = append(row, map[string]string{"text": x.Text, "callback_data": x.Data})
			}
			kb = append(kb, row)
		}
		j, _ := json.Marshal(map[string]any{"inline_keyboard": kb})
		form.Set("reply_markup", string(j))
	}
	var out struct {
		ID int64 `json:"message_id"`
	}
	err := b.call("sendMessage", form, &out)
	return out.ID, err
}

// Answer: 콜백 버튼 응답 (토스트) + 버튼 제거.
func (b *Bot) Answer(callbackID string, toast string, msgID int64, newText string) {
	_ = b.call("answerCallbackQuery", url.Values{"callback_query_id": {callbackID}, "text": {toast}}, nil)
	if msgID > 0 && newText != "" {
		_ = b.call("editMessageText", url.Values{"chat_id": {b.Chat}, "message_id": {strconv.FormatInt(msgID, 10)}, "text": {newText}, "disable_web_page_preview": {"true"}}, nil)
	}
}

// Allowed: 허용된 채팅에서 온 업데이트인가.
func (b *Bot) Allowed(u Update) bool {
	id := int64(0)
	if u.Message != nil {
		id = u.Message.Chat.ID
	} else if u.Callback != nil && u.Callback.Msg != nil {
		id = u.Callback.Msg.Chat.ID
	}
	return strings.TrimSpace(b.Chat) == strconv.FormatInt(id, 10)
}
