package agent

import (
	"fmt"
	"log/slog"
	"sort"
	"strconv"
	"time"

	"github.com/hkjang/Quantoss/internal/broker"
	"github.com/hkjang/Quantoss/internal/market"
	"github.com/hkjang/Quantoss/internal/toss"
)

// startRealtime: WebSocket 체결 구독으로 손절/익절을 즉시 감시하고, 본인 주문 이벤트로 외부 체결(서버 손절)을 반영한다.
// 시세 채널은 LOSSY 이므로 REST 폴링은 계속 병행한다.
func (a *Agent) startRealtime() {
	if !a.cfg.Realtime {
		return
	}
	a.ws = a.client.NewWS(toss.WSHandlers{
		OnTrade: a.onTrade,
		OnOrder: a.onOrderEvent,
		OnState: func(connected bool, reason string) {
			if connected {
				slog.Info("ws 연결됨")
				a.wsDownSince = time.Time{}
			} else {
				if a.wsDownSince.IsZero() {
					a.wsDownSince = time.Now()
				}
				slog.Warn("ws 끊김 (REST 폴링으로 계속)", "reason", reason)
			}
		},
	})
	a.ws.Start()
}

func (a *Agent) refreshSubscriptions() {
	if a.ws == nil {
		return
	}
	syms := append([]string{}, a.universe...)
	for s := range a.broker.Positions() {
		syms = append(syms, s)
	}
	sort.Strings(syms)
	uniq := syms[:0]
	for i, s := range syms {
		if i == 0 || s != syms[i-1] {
			uniq = append(uniq, s)
		}
	}
	acct := 0
	if _, ok := a.broker.(*broker.Live); ok {
		acct = a.client.AccountSeq
	}
	a.ws.Subscribe(market.SpecOf(a.cfg.Country).WSType, uniq, acct)
}

// onTrade: 보유 종목의 체결가가 손절/목표에 닿으면 즉시 엔진을 호출한다 (틱 대기 없이).
func (a *Agent) onTrade(t toss.WSTrade) {
	a.mu.Lock()
	defer a.mu.Unlock()
	a.lastPx[t.Symbol] = t.Price
	pos := a.broker.Positions()[t.Symbol]
	if pos == nil || (t.Price > pos.Stop && t.Price < pos.TakeProfit) {
		return
	}
	bars := a.bars[t.Symbol]
	if len(bars) == 0 {
		return
	}
	now := time.Now().In(a.cfg.Loc)
	cur := now.Truncate(time.Minute)
	n := sort.Search(len(bars), func(i int) bool { return !bars[i].TS.Before(cur) })
	px := t.Price
	a.engine.OnUpdate(t.Symbol, bars[:n], now, &px)
}

// onOrderEvent: 이 프로세스가 내지 않은 SELL 체결(서버 조건주문·수동)을 포지션에 반영한다.
func (a *Agent) onOrderEvent(ev toss.WSOrderEvent) {
	o := ev.Order
	if ev.Event != "FILL" || o.Side != "SELL" || o.Status != "FILLED" {
		return
	}
	es, ok := a.broker.(broker.ExternalSeller)
