func Load(dataDir, mode, date string) *Journal {
	j := NewForMode(dataDir, mode)
	readLines(j.FlowsPath, func(line string) {
		var f FlowEvent
		if json.Unmarshal([]byte(line), &f) == nil && (date == "" || strings.HasPrefix(f.TS, date)) {
			j.Flows = append(j.Flows, f)
		}
	})
	readLines(j.Path, func(line string) {
		var t ClosedTrade
		if json.Unmarshal([]byte(line), &t) == nil && (date == "" || strings.HasPrefix(t.ExitTime, date)) {
			j.Trades = append(j.Trades, t)
		}
	})
	readLines(j.EquityPath, func(line string) {
		var p EquityPoint
		if json.Unmarshal([]byte(line), &p) == nil && (date == "" || strings.HasPrefix(p.TS, date)) {
			j.Equity = append(j.Equity, p)
		}
	})
	j.Path, j.EquityPath, j.FlowsPath = "", "", "" // 읽기 전용
	return j
}

