// 두 클라이언트(프로세스 역할)가 같은 캐시 파일을 쓰면 두 번째는 토큰을 재발급하지 않고 캐시를 쓴다.
func TestTokenCacheShared(t *testing.T) {
	path := filepath.Join(t.TempDir(), ".token.json")
	a := &Client{ClientID: "id", ClientSecret: "s", TokenCache: path}
	a.token, a.tokenExp = "tok-A", time.Now().Add(time.Hour)
	a.saveTokenCache()

	b := &Client{ClientID: "id", ClientSecret: "s", TokenCache: path}
	if !b.loadTokenCache() || b.token != "tok-A" {
		t.Fatalf("second process should reuse cached token, got %q", b.token)
	}
	// 다른 client_id 의 캐시는 쓰지 않는다
	c := &Client{ClientID: "other", ClientSecret: "s", TokenCache: path}
	if c.loadTokenCache() {
		t.Fatal("cache for a different client id must be ignored")
	}
	// 만료 임박 캐시는 무시
	a.tokenExp = time.Now().Add(time.Minute)
	a.saveTokenCache()
	if b.loadTokenCache() {
		t.Fatal("near-expiry cache must be ignored")
	}
}
# Quantoss 혁신 기능 제안 (2026-09-17)

목표: "기능이 많은 서비스" 가 아니라 **한 번 쓰면 예전 방식(앱 열고 확인·계산·주문·리포트)으로 돌아가기 어려운 서비스**.
서비스의 목적은 "작은 계좌를 규칙으로 불리되, 사람이 매일 판단하지 않아도 굴러가고 틀리면 스스로 알아채는 것" 이다.
원칙은 유지한다: 파일+Git+Pages(DB 없음), LLM 은 매매 판단을 하지 않는다(§11), 돈이 움직이는 행동은 사람이 확인한다.

**구현 상태**: ★ = 이번에 구현 완료 (`quantoss copilot`), ☆ = 설계만.

| # | 기능 | 한 줄 | 난이도 | 상태 |
